// Minimal client for Bolt Database (Supabase): PostgREST for data, GoTrue for auth.
// It uses only fetch, so there is no extra package to install. Row access is enforced
// by the database's row level security policies; this file only builds requests.

const TABLE_RE = /^[a-z][a-z0-9_]*$/;
const SESSION_KEY = 'urf_session';
const REFRESH_MARGIN_MS = 60_000;
// Generated by the database, so they must never be written back.
const READ_ONLY_COLUMNS = ['id', 'created_at'];

const fail = (error, httpStatus) => ({ status: 'error', data: null, error, httpStatus });
const ok = (data) => ({ status: 'success', data });

// Turns the app's path style ("read/sermons?sort=date:desc&limit=5") into a PostgREST request.
export function translate(path, options = {}) {
  const [route, queryString = ''] = path.split('?');
  const [action, table, id] = route.split('/');
  if (!TABLE_RE.test(table || '')) return { error: `Invalid table name: ${table}` };

  const params = new URLSearchParams(queryString);
  const method = (options.method || 'GET').toUpperCase();
  const clean = (raw) => {
    let body = {};
    try { body = raw ? JSON.parse(raw) : {}; } catch { return null; }
    for (const col of READ_ONLY_COLUMNS) delete body[col];
    return body;
  };

  if (action === 'read') {
    const q = new URLSearchParams({ select: '*' });
    let sort = params.get('sort');
    let dir = params.get('order') || 'asc';
    if (sort?.includes(':')) [sort, dir] = sort.split(':');
    const order = [];
    if (sort) order.push(`${sort}.${dir === 'desc' ? 'desc' : 'asc'}`);
    order.push('id.asc');
    for (const col of order.map(o => o.split('.')[0])) {
      if (!TABLE_RE.test(col)) return { error: `Invalid sort column: ${col}` };
    }
    q.set('order', order.join(','));
    if (params.get('limit')) q.set('limit', String(Number(params.get('limit')) || 0));
    if (params.get('offset')) q.set('offset', String(Number(params.get('offset')) || 0));
    for (const [key, value] of params) {
      if (['sort', 'order', 'limit', 'offset'].includes(key)) continue;
      if (!TABLE_RE.test(key)) return { error: `Invalid filter: ${key}` };
      q.append(key, `eq.${value}`);
    }
    return { table, method: 'GET', query: q.toString() };
  }

  if (action === 'create') {
    const body = clean(options.body);
    if (body === null) return { error: 'Invalid JSON body' };
    return { table, method: 'POST', query: '', body };
  }

  if (action === 'update' || action === 'delete') {
    if (!id || !/^\d+$/.test(id)) return { error: 'A numeric id is required' };
    const q = `id=eq.${id}`;
    if (action === 'delete') return { table, method: 'DELETE', query: q };
    const body = clean(options.body);
    if (body === null) return { error: 'Invalid JSON body' };
    return { table, method: 'PATCH', query: q, body };
  }

  return { error: `Unknown action: ${action}` };
}

export function createBackend({
  url = '',
  anonKey = '',
  storage = typeof localStorage !== 'undefined' ? localStorage : null,
  fetchImpl = (...args) => fetch(...args),
  now = () => Date.now(),
} = {}) {
  const base = url.replace(/\/$/, '');
  const configured = Boolean(base && anonKey);
  let refreshing = null;

  const readSession = () => {
    try { return JSON.parse(storage?.getItem(SESSION_KEY) || 'null'); } catch { return null; }
  };
  const writeSession = (s) => {
    try { s ? storage?.setItem(SESSION_KEY, JSON.stringify(s)) : storage?.removeItem(SESSION_KEY); } catch { /* storage unavailable */ }
  };

  const errorText = (body, status) =>
    body?.error_description || body?.msg || body?.message || body?.error || `HTTP ${status}`;

  // Database errors carry schema, constraint and policy detail, so the interface gets a
   // generic message for the status instead of the backend's own text.
  const dataErrorText = (status) => {
    if (status === 401 || status === 403) return 'You are not signed in, or you do not have permission to do that.';
    if (status === 404) return 'That item no longer exists.';
    if (status === 409) return 'That conflicts with something that already exists.';
    if (status === 400 || status === 422) return 'Some of the details sent were not valid. Please check the form and try again.';
    return 'Something went wrong. Please try again.';
  };

  const tokenToSession = (t) => ({
    access_token: t.access_token,
    refresh_token: t.refresh_token,
    expires_at: t.expires_at || Math.floor(now() / 1000) + (t.expires_in || 3600),
    user: t.user,
  });

  async function authCall(path, { method = 'POST', body, token } = {}) {
    const res = await fetchImpl(`${base}/auth/v1/${path}`, {
      method,
      headers: {
        apikey: anonKey,
        'Content-Type': 'application/json',
        ...(token ? { Authorization: `Bearer ${token}` } : {}),
      },
      body: body ? JSON.stringify(body) : undefined,
    });
    const json = await res.json().catch(() => ({}));
    return { res, json };
  }

  async function refresh(session) {
    if (!refreshing) {
      refreshing = (async () => {
        try {
          const { res, json } = await authCall('token?grant_type=refresh_token', { body: { refresh_token: session.refresh_token } });
          if (!res.ok || !json.access_token) { writeSession(null); return null; }
          const next = tokenToSession(json);
          writeSession(next);
          return next;
        } catch {
          return session; // offline: keep the old session, the next call will retry
        } finally {
          refreshing = null;
        }
      })();
    }
    return refreshing;
  }

  // The signed-in user's token when there is one, otherwise the anonymous key.
  async function getToken() {
    let session = readSession();
    if (!session) return anonKey;
    if (session.expires_at * 1000 - now() < REFRESH_MARGIN_MS) session = await refresh(session);
    return session?.access_token || anonKey;
  }

  async function signIn(email, password) {
    if (!configured) return fail('The backend is not configured', 0);
    try {
      const { res, json } = await authCall('token?grant_type=password', { body: { email, password } });
      if (!res.ok || !json.access_token) {
        const bad = res.status === 400 || res.status === 401;
        return fail(bad ? 'Incorrect email or password' : errorText(json, res.status), res.status);
      }
      const session = tokenToSession(json);
      writeSession(session);
      return ok(session.user);
    } catch (err) {
      return fail(err?.message || 'Network error', 0);
    }
  }

  async function signOut() {
    const session = readSession();
    writeSession(null);
    if (session && configured) {
      try { await authCall('logout', { token: session.access_token }); } catch { /* already signed out locally */ }
    }
  }

  // Confirms the stored session with the server and returns the user, or null.
  async function getUser() {
    if (!configured || !readSession()) return null;
    try {
      const token = await getToken();
      if (token === anonKey) return null;
      const { res, json } = await authCall('user', { method: 'GET', token });
      if (res.status === 401 || res.status === 403) { writeSession(null); return null; }
      // The stored session is never trusted on its own: if the server did not confirm
      // it, the user is treated as signed out.
      if (!res.ok) return null;
      return json;
    } catch {
      return null;
    }
  }

  async function data(path, options = {}, { minimal = false } = {}) {
    if (!configured) return fail('The backend is not configured. Set VITE_SUPABASE_URL and VITE_SUPABASE_ANON_KEY.', 0);
    const req = translate(path, options);
    if (req.error) return fail(req.error, 400);

    try {
      const token = await getToken();
      const headers = { apikey: anonKey, Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' };
      // Anonymous visitors may insert rows they are not allowed to read back (contact form).
      if (req.method === 'POST' && minimal) headers.Prefer = 'return=minimal';
      else if (req.method !== 'GET') headers.Prefer = 'return=representation';

      const res = await fetchImpl(`${base}/rest/v1/${req.table}${req.query ? `?${req.query}` : ''}`, {
        method: req.method,
        headers,
        body: req.body ? JSON.stringify(req.body) : undefined,
      });
      const json = await res.json().catch(() => null);
      if (!res.ok) return fail(dataErrorText(res.status), res.status);

      if (req.method === 'GET') return ok(Array.isArray(json) ? json : []);
      if (req.method === 'POST') return ok(Array.isArray(json) ? json[0] ?? {} : {});
      // PATCH and DELETE return the affected rows. None means the policy blocked it or the id is gone.
      if (!Array.isArray(json) || json.length === 0) {
        return fail('Nothing was changed. You may not have permission, or the item no longer exists.', 403);
      }
      return ok(json[0]);
    } catch (err) {
      return fail(err?.message || 'Network error', 0);
    }
  }

  return { configured, signIn, signOut, getUser, data, getToken };
}

export const backend = createBackend({
  url: import.meta.env.VITE_SUPABASE_URL,
  anonKey: import.meta.env.VITE_SUPABASE_ANON_KEY,
});
